def attach_readings(sensors, latest):
    result = []
    for sensor in sensors:
        sensor_id = sensor['sensor_id']
        reading = latest.get(sensor_id, None)
        if reading is None or reading == 0:
            result.append({'sensor_id': sensor_id, 'reading': None})
        else:
            result.append({'sensor_id': sensor_id, 'reading': reading})
    return result
