def pad_rows(rows, width, fill=None):
    if width < 0:
        raise ValueError("Width cannot be negative")

    padded_rows = []
    for row in rows:
        if isinstance(row, list):
            # Pad the list to the specified width
            padded_row = row[:]
            if len(padded_row) < width:
                padded_row += [fill] * (width - len(padded_row))
            else:
                padded_row = padded_row[:width]
        elif isinstance(row, tuple):
            # Pad the tuple to the specified width
            padded_row = tuple(row[:])
            if len(padded_row) < width:
                padded_row += (fill,) * (width - len(padded_row))
            else:
                padded_row = padded_row[:width]
        else:
            # For other iterables, treat as a single element
            padded_row = [row]
            if len(padded_row) < width:
                padded_row += [fill] * (width - len(padded_row))
            else:
                padded_row = padded_row[:width]

        padded_rows.append(padded_row)

    return padded_rows
